    # State names: S0, S1, S11, S110, FOUND
    state = "S0"
    cur = {"reset": 0, "data": 0}
    outs = []

    for row in vectors:
        # Drive row's values before the sampled posedge. Missing inputs retain
        # any mid-cycle value carried from the previous row.
        for name in ("reset", "data"):
            if name in row:
                cur[name] = row[name]

        reset = cur["reset"]
        data = cur["data"]

        # R_RESET_CLEAR: synchronous active-high reset at the sampled posedge
        # forces FSM state S0 and start_shifting=0 on the settled edge.
        if reset == 1:
            next_state = "S0"
            start_shifting = 0
        else:
            # R_SET_OR_HOLD_1101: detection completes 1101 here; FOUND is sticky
            # and start_shifting becomes/remains 1 after the settled posedge.
            if state == "FOUND":
                next_state = "FOUND"
                start_shifting = 1
            elif state == "S110" and data == 1:
                next_state = "FOUND"
                start_shifting = 1
            else:
                # R_KEEP_ZERO_UNTIL_FOUND: before detection and after non-matching
                # transitions, start_shifting remains 0 after the settled posedge.
                start_shifting = 0
                if state == "S0":
                    next_state = "S1" if data == 1 else "S0"
                elif state == "S1":
                    next_state = "S11" if data == 1 else "S0"
                elif state == "S11":
                    next_state = "S11" if data == 1 else "S110"
                elif state == "S110":
                    next_state = "FOUND" if data == 1 else "S0"
                else:
                    next_state = "S0"

        # Output visible after the posedge edge settles; it reflects the new state.
        outs.append({"start_shifting": int(start_shifting)})
        state = next_state

        # Optional mid input changes occur AFTER sampling and are carried to the
        # start of the next row. They do not change this row's settled output.
        mid = row.get("mid") if isinstance(row, dict) else None
        if mid:
            if isinstance(mid, dict):
                for name in ("reset", "data"):
                    if name in mid:
                        cur[name] = mid[name]
            elif isinstance(mid, list):
                for change in mid:
                    if isinstance(change, dict):
                        for name in ("reset", "data"):
                            if name in change:
                                cur[name] = change[name]
                    elif isinstance(change, (tuple, list)) and len(change) >= 2:
                        name = change[0]
                        if name in ("reset", "data"):
                            cur[name] = change[1]

    return outs

def reference(vectors):
    # State encoding: 0=S0, 1=S1, 2=S11, 3=S110, 4=FOUND
    state = 0
    start_shifting = 0
    current_reset = 0
    current_data = 0
    results = []

    for row in vectors:
        # R_KEEP_ZERO_UNTIL_FOUND: apply driven inputs before sampled posedge
        if "reset" in row:
            current_reset = row["reset"] & 1
        if "data" in row:
            current_data = row["data"] & 1

        reset = current_reset
        data = current_data

        if reset == 1:
            # R_RESET_CLEAR: synchronous active-high reset forces S0 and start_shifting=0
            state = 0
            start_shifting = 0
        else:
            # R_SET_OR_HOLD_1101: detection sets start_shifting=1 and FOUND holds it
            if state == 4:  # FOUND
                state = 4
                start_shifting = 1
            elif state == 3:  # S110
                if data == 1:
                    state = 4  # FOUND
                    start_shifting = 1
                else:
                    state = 0  # S0
                    start_shifting = 0
            elif state == 2:  # S11
                if data == 1:
                    state = 2  # S11 (overlapping 1s)
                else:
                    state = 3  # S110
                start_shifting = 0
            elif state == 1:  # S1
                if data == 1:
                    state = 2  # S11
                else:
                    state = 0  # S0
                start_shifting = 0
            else:  # S0
                if data == 1:
                    state = 1  # S1
                else:
                    state = 0  # S0
                start_shifting = 0

        # R_KEEP_ZERO_UNTIL_FOUND: outputs are settled after the sampled posedge
        results.append({"start_shifting": start_shifting & 1})

        # Mid changes occur AFTER sampling, before the other edge, and carry to next row
        if "mid" in row:
            mid = row["mid"]
            if mid is not None:
                for k in mid:
                    if k == "reset":
                        current_reset = mid[k] & 1
                    elif k == "data":
                        current_data = mid[k] & 1

    return results
